mapper.select:
select id, event_type, event_id, recipient_id, channel, status, provider_code
from notification_delivery_receipt
where event_type=#{eventType} and event_id=#{eventId}
  and recipient_id=#{recipientId} and channel=#{channel}

mapper.update:
update notification_delivery_receipt set status='PROCESSING', provider_code=null, update_time=now()
where event_type=#{eventType} and event_id=#{eventId}
  and recipient_id=#{recipientId} and channel=#{channel}
  and status in ('PENDING', 'FAILED')

update notification_delivery_receipt set status='PROCESSING', provider_code=null, update_time=now()
where event_type=#{eventType} and event_id=#{eventId}
  and recipient_id=#{recipientId} and channel=#{channel} and status='PENDING'
